class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        visited = {}

        list_length = len(nums)
        for i in range(list_length):
            curr = nums[i]
            nr = target - curr
            if nr in visited:
                return [visited[nr], i]

            visited[curr] = i

        return []

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        visited = set()
        left = 0
        max_length = 0

        s_length = len(s)
        for i in range(s_length):
            while s[i] in visited:
                visited.remove(s[left])
                left += 1

            visited.add(s[i])
            curr = i - left + 1
            if curr > max_length:
                max_length = curr

        return max_length

class Solution:
    def longestPalindrome(self, s: str) -> str:
        ret = ""
        ret_length = 0

        s_length = len(s)
        for i in range(s_length):
            l = i
            r = i
            while l >= 0 and r < s_length and s[l] == s[r]:
                if (r - l + 1) > ret_length:
                    ret = s[l:r + 1]
                    ret_length = r - l + 1
                l -= 1
                r += 1

            l = i
            r = i + 1
            while l >= 0 and r < s_length and s[l] == s[r]:
                if (r - l + 1) > ret_length:
                    ret = s[l:r + 1]
                    ret_length = r - l + 1
                l -= 1
                r += 1

        return ret

