class Solution:
    def maxArea(self, height: List[int]) -> int:
        left = 0
        height_length = len(height)
        right = height_length - 1

        maximum = 0
        while left < right:
            width = right - left
            minim_height = min(height[left], height[right])

            curr = width * minim_height
            if curr > maximum:
                maximum = curr

            if height[left] < height[right]:
                left += 1
            else:
                right -= 1


        return maximum

class Solution:
    def romanToInt(self, s: str) -> int:
        roman = {
            "I": 1,
            "V": 5,
            "X": 10,
            "L": 50,
            "C": 100,
            "D": 500,
            "M": 1000
        }

        total = 0

        for i in range(len(s)):
            if i + 1 < len(s) and roman[s[i]] < roman[s[i + 1]]:
                total -= roman[s[i]]
            else:
                total += roman[s[i]]

        return total

class Solution:
    def longestCommonPrefix(self, strs: list[str]) -> str:
        prefix = min(strs)

        while prefix:
            nr = 0
            for word in strs:
                if word.startswith(prefix):
                    nr += 1
                else:
                    break
            if nr == len(strs):
                return prefix
            prefix = prefix[:-1]

        return ""

class Solution:
    def threeSum(self, nums: list[int]) -> list[list[int]]:
        ret = []

        nums.sort()
        nums_length = len(nums)
        for i in range(nums_length):
            if i > 0 and nums[i] == nums[i-1]:
                continue
            left = i + 1
            right = nums_length - 1

            while left < right:
                sum3 = nums[i] + nums[left] + nums[right]
                if sum3 > 0:
                    right -= 1
                elif sum3 < 0:
                    left += 1
                else:
                    ret.append([nums[i], nums[left], nums[right]])

                    # skip the duplicates
                    left += 1
                    while left < right and nums[left] == nums[left - 1]:
                        left += 1

        return ret

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []

        s_map = {
            ')': '(', 
            '}': '{', 
            ']': '['
        }

        for c in s:
            if c in s_map:
                curr = '#'
                if stack:
                    curr = stack.pop()

                if s_map[c] != curr:
                    return False

            else:
                stack.append(c)

        return not stack

