class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i = len(a) - 1
        j = len(b) - 1
        carry = 0
        result = []

        while i >= 0 or j >= 0 or carry:
            total = carry

            if i >= 0:
                total += int(a[i])
                i -= 1

            if j >= 0:
                total += int(b[j])
                j -= 1

            result.append(str(total % 2))
            carry = total // 2

        return ''.join(reversed(result))

class Solution:
    def mySqrt(self, x: int) -> int:
        low = 0
        high = x
        answer = 0

        while low <= high:
            mid = (low + high) // 2

            if mid * mid == x:
                return mid

            if mid * mid < x:
                answer = mid
                low = mid + 1
            else:
                high = mid - 1

        return answer

class Solution:
    def climbStairs(self, n: int) -> int:
        if n <= 2:
            return n

        dp = [0] * (n + 1)
        dp[1] = 1
        dp[2] = 2
        for i in range (3, n + 1):
            dp[i] = dp[i-1] + dp[i-2]

