class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def f(node, low=float('-inf'), high=float('inf')):
            if not node:
                return True

            if not (low < node.val < high):
                return False

            return f(node.left, low, node.val) and f(node.right, node.val, high)

        return f(root)

