            while i < n and expression[i] == ',':
                i += 1
                result |= parse_term()

            return result

        def parse_term():
            nonlocal i

            result = {""}

            while i < n and expression[i] not in '},':
                factor = parse_factor()
                result = {
                    a + b
                    for a in result
                    for b in factor
                }

            return result

        def parse_factor():
            nonlocal i
            if expression[i] == '{':
                i += 1
                result = parse_expression()
                i += 1
                return result
            start = i
            while i < n and expression[i].islower():
                i += 1

            return {expression[start:i]}

        return sorted(parse_expression())

class Solution:
    def maxDepthAfterSplit(self, seq: str) -> list[int]:
        result = []
        depth = 0

        for c in seq:
            if c == '(':
                depth += 1
                result.append(depth % 2)
            else:
                result.append(depth % 2)
                depth -= 1

        return result

class Solution:
    def tribonacci(self, n: int) -> int:
        a, b, c = 0, 1, 1

        for _ in range(n):
            a, b, c = b, c, a + b + c

        return a

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        n1 = len(text1)
        n2 = len(text2)

        dp = [[0] * (n2 + 1) for x in range(n1 + 1)]

        for i in range(1, n1 + 1):
            for j in range(1, n2 + 1):
                if text1[i - 1] == text2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        return dp[n1][n2]

class Solution:
    def reverseParentheses(self, s: str) -> str:
        stack = []
        current = ""

        for char in s:
            if char == "(":
                stack.append(current)
                current = ""

            elif char == ")":
                current = current[::-1]
                current = stack.pop() + current

            else:
                current += char

        return current

class Solution:
    def minSumOfLengths(self, arr: list[int], target: int) -> int:
        n = len(arr)
        best = [float('inf')] * n

        left = 0
        current_sum = 0
        shortest = float('inf')
        answer = float('inf')

        for right in range(n):
            current_sum += arr[right]

            while current_sum > target:
                current_sum -= arr[left]
                left += 1

            if current_sum == target:
                length = right - left + 1

                if left > 0 and best[left - 1] != float('inf'):
                    answer = min(answer, length + best[left - 1])

                shortest = min(shortest, length)

            best[right] = shortest

        return answer if answer != float('inf') else -1

class Solution:
    def maxNumOfSubstrings(self, s: str) -> list[str]:
        first = [len(s)] * 26
        last = [-1] * 26

        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            first[idx] = min(first[idx], i)
            last[idx] = i

        intervals = []

        for i in range(26):
            if last[i] == -1:
                continue

            left = first[i]
            right = last[i]
            j = left
            valid = True

            while j <= right:
                idx = ord(s[j]) - ord('a')

                if first[idx] < left:
                    valid = False
                    break

                right = max(right, last[idx])
                j += 1

            if valid:
                intervals.append((left, right))

        intervals.sort(key=lambda x: x[1])

        result = []
        end = -1

        for left, right in intervals:
            if left > end:
                result.append(s[left:right + 1])
                end = right

        return result

class Solution:
    def maxDepth(self, s: str) -> int:
        nrmax = 0

        cnt = 0
        for c in s:
            if c == '(':
                cnt += 1
                if cnt > nrmax:
                    nrmax = cnt
            if c == ')':
                cnt -= 1

        return nrmax

class Solution:
    def numberOfSets(self, n: int, k: int) -> int:
        from math import comb
        return comb(n + k - 1, 2 * k) % (10**9 + 7)

class Solution:
    def minOperations(self, nums: list[int], x: int) -> int:
        target = sum(nums) - x
        n = len(nums)

        if target < 0:
            return -1

        left = 0
        curr_sum = 0
        max_len = -1

        for right in range(n):
            curr_sum += nums[right]

            while curr_sum > target and left <= right:
                curr_sum -= nums[left]
                left += 1

            if curr_sum == target:
                max_len = max(max_len, right - left + 1)

        return -1 if max_len == -1 else n - max_len

class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        count = 0
        current = word

        while current in sequence:
            count += 1
            current += word

        return count

class Solution:
    def evaluate(self, s: str, knowledge: list[list[str]]) -> str:
        values = {}
        for key, value in knowledge:
            values[key] = value

        result = []
        i = 0
        while i < len(s):
            if s[i] == '(':
                i += 1

                key = ""
                while s[i] != ')':
                    key += s[i]
                    i += 1
                if key in values:
                    result.append(values[key])
                else:
                    result.append("?")
                i += 1
            else:
                result.append(s[i])
                i += 1

        return "".join(result)

class Solution:
    def hasValidPath(self, grid: list[list[str]]) -> bool:
        m = len(grid)
        n = len(grid[0])

        if (m + n - 1) % 2 == 1:
            return False

        if grid[0][0] == ')':
            return False

        if grid[m - 1][n - 1] == '(':
            return False

        dp = [[set() for _ in range(n)] for _ in range(m)]

        dp[0][0].add(1)

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                if i > 0:
                    for balance in dp[i - 1][j]:
                        if grid[i][j] == '(':
                            new_balance = balance + 1
                        else:
                            new_balance = balance - 1

                        if new_balance >= 0:
                            dp[i][j].add(new_balance)

                if j > 0:
                    for balance in dp[i][j - 1]:
                        if grid[i][j] == '(':
                            new_balance = balance + 1
                        else:
                            new_balance = balance - 1

                        if new_balance >= 0:
                            dp[i][j].add(new_balance)

        return 0 in dp[m - 1][n - 1]

class Solution:
    def getLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
