class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0

        for i, char in enumerate(s):
            value = ord('z') - ord(char) + 1
            total += value * (i + 1)

        return total

class Solution:
    def resultArray(self, nums: List[int], k: int) -> List[int]:
        ans = [0] * k
        prev = [0] * k

        for num in nums:
            x = num % k
            curr = [0] * k

            curr[x] += 1

            for r in range(k):
                if prev[r]:
                    curr[(r * x) % k] += prev[r]

            for r in range(k):
                ans[r] += curr[r]

            prev = curr

        return ans

class Solution:
    def resultArray(self, nums: List[int], k: int, queries: List[List[int]]) -> List[int]:
        n = len(nums)

        tree = [[1, [0] * k] for _ in range(4 * n)]

        def merge(left, right):
            product_left, count_left = left
            product_right, count_right = right
            product = (product_left * product_right) % k
            count = count_left[:]
            for r in range(k):
                new_r = (product_left * r) % k
                count[new_r] += count_right[r]

            return [product, count]

        def build(node, left, right):
            if left == right:
                value = nums[left] % k

                tree[node][0] = value
                tree[node][1][value] = 1

                return

            mid = (left + right) // 2

            build(node * 2, left, mid)
            build(node * 2 + 1, mid + 1, right)

            tree[node] = merge(
                tree[node * 2],
                tree[node * 2 + 1]
            )

        def update(node, left, right, index, value):
            if left == right:
                value %= k

                tree[node][0] = value
                tree[node][1] = [0] * k
                tree[node][1][value] = 1

                return

            mid = (left + right) // 2

            if index <= mid:
                update(node * 2, left, mid, index, value)
            else:
                update(node * 2 + 1, mid + 1, right, index, value)

            tree[node] = merge(
                tree[node * 2],
                tree[node * 2 + 1]
            )

        def query(node, left, right, ql, qr):
            if ql <= left and right <= qr:
                return tree[node]

            mid = (left + right) // 2
            if qr <= mid:
                return query(node * 2, left, mid, ql, qr)
            if ql > mid:
                return query(node * 2 + 1, mid + 1, right, ql, qr)
            left_result = query(node * 2, left, mid, ql, qr)
            right_result = query(node * 2 + 1, mid + 1, right, ql, qr)

            return merge(left_result, right_result)

        build(1, 0, n - 1)

        answer = []
        for index, value, start, x in queries:
            update(1, 0, n - 1, index, value)
            result = query(1, 0, n - 1, start, n - 1)

            answer.append(result[1][x])

        return answer

class Solution:
    def smallestIndex(self, nums: List[int]) -> int:
        def digit_sum(n):
            return sum(int(c) for c in str(n))

        for i, x in enumerate(nums):
            if i == digit_sum(x):
                return i

        return -1

class Solution:
    def firstStableIndex(self, nums: list[int], k: int) -> int:
        n = len(nums)
        suffix_min = [0] * n
        suffix_min[n - 1] = nums[n - 1]

        for i in range(n - 2, -1, -1):
            suffix_min[i] = min(nums[i], suffix_min[i + 1])

        max_left = nums[0]
        for i in range(n):
            max_left = max(max_left, nums[i])
            score = max_left - suffix_min[i]
            if score <= k:
                return i

        return -1

class Solution:
    def sumOfGoodIntegers(self, n: int, k: int) -> int:
        ans = 0

        for x in range(max(1, n - k), n + k + 1):
            if (n & x) == 0:
                ans += x

        return ans
